{
  "loaded": [
    {
      "tool_id": "hirearchy::report",
      "description": "Answer a task assigned to you. Goes to whoever assigned it.\n\n        status: \"done\" (every acceptance criterion verifiably met), \"failed\", or \"blocked\" (say what would unblock it).\n        `done` and `failed` are final: a second report is refused. `blocked` is not: once the blocker is resolved\n        you may report the task again, once per blocked report (any status; the new report supersedes the old one),\n        under the same rules. A `send` note never changes a task's outcome and must not claim criteria are met.\n        summary: at most ~10 lines; this is all your manager reads by default. artifacts: paths of the\n        files that hold the work; they must exist. Files in the organization: path relative to the org root.\n        Files in your workspace: the ABSOLUTE path (anything else outside the organization is refused). The runtime\n        annotates each with its word count and whether it changed since the task was assigned.\n        lessons: required when the task is a request for a service, whatever the status - done, failed or blocked\n        (at most 800 characters). Write an after-action review in labelled parts: Expected: <the criterion id or step it\n        concerns>. Happened: <what the work did>. Caught at: <where it should have been caught>. Cause: <the system\n        cause: a step, a check, a hand-off, an input; not a person>. Prevent: <what would have prevented it>. When\n        nothing went wrong: Near miss: <what almost went wrong, or none>. It is recorded in the result and shown to\n        the service's owner before the next request, as its team's view. Optional otherwise.\n        ",
      "input_schema": {
        "type": "object",
        "properties": {
          "task_id": {
            "title": "Task Id",
            "type": "string"
          },
          "status": {
            "title": "Status",
            "type": "string"
          },
          "summary": {
            "title": "Summary",
            "type": "string"
          },
          "artifacts": {
            "anyOf": [
              {
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Artifacts"
          },
          "lessons": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Lessons"
          }
        },
        "required": [
          "task_id",
          "status",
          "summary"
        ]
      }
    },
    {
      "tool_id": "hirearchy::write",
      "description": "Write an ORGANIZATION file (kiro shows this tool as @hirearchy/write; it is NOT kiro's built-in `write`, which\n        writes the workspace). Use it for your memory, notes and artifacts inside your own org directory. Paths are\n        relative to the org root, like every path here, so they start with your address: e.g. \"<you>/MEMORY.md\" or\n        \"<you>/work/plan.md\".\n\n        You may also rewrite a direct report's charter (\"<you>/<name>/AGENT.md\"). Inboxes, logs and your own\n        charter are managed by the runtime; use send/delegate/report to communicate. A charter rewrite keeps every\n        frontmatter key (tools, inputs, model, ...) that your new text does not set; the reply lists what was kept\n        and what changed.\n        ",
      "input_schema": {
        "type": "object",
        "properties": {
          "path": {
            "title": "Path",
            "type": "string"
          },
          "content": {
            "title": "Content",
            "type": "string"
          },
          "append": {
            "default": false,
            "title": "Append",
            "type": "boolean"
          }
        },
        "required": [
          "path",
          "content"
        ]
      }
    },
    {
      "tool_id": "hirearchy::delegate",
      "description": "Assign a task to one of your direct reports.\n\n        to: the report's address (e.g. \"ceo/cto\"). title: a few words. goal: what outcome is needed and why.\n        acceptance: concrete, checkable criteria for \"done\". inputs: paths (relative to the org root) the\n        report should read. budget: runs handed to the report from your own budget. If you omit it, the default is\n        min(default_budget from ORG.md, your budget - reserve), where the reserve keeps one run per outstanding\n        delegation plus one for this one; if that is below 1 the call fails and tells you your options.\n        An explicit budget must leave that same reserve.\n        Copy the relevant acceptance criteria verbatim from the task you are working on; never paraphrase or relax them.\n        revises: when sending work back for rework, the id of the earlier task you sent to the same report.\n        Returns the task id. Do not wait for the result: end your run, the result will wake you.\n        ",
      "input_schema": {
        "type": "object",
        "properties": {
          "to": {
            "title": "To",
            "type": "string"
          },
          "title": {
            "title": "Title",
            "type": "string"
          },
          "goal": {
            "title": "Goal",
            "type": "string"
          },
          "acceptance": {
            "title": "Acceptance",
            "type": "string"
          },
          "inputs": {
            "anyOf": [
              {
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Inputs"
          },
          "budget": {
            "anyOf": [
              {
                "type": "integer"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Budget"
          },
          "revises": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Revises"
          }
        },
        "required": [
          "to",
          "title",
          "goal",
          "acceptance"
        ]
      }
    }
  ],
  "not_found": [],
  "note": "These tools are now loaded for the rest of this session. To RUN one, call tool_call with { \"tool_id\": \"namespace::tool\", \"arguments\": { ... } } (use the tool_id shown for each result, and arguments matching its input_schema). Do not call tool_load again for tools you have already loaded."
}
